<?php require_once dirname(__DIR__).'/includes/functions.php';require_content_manager();$rows=$con->query('SELECT * FROM career_categories ORDER BY name');$pageTitle='Categories';require __DIR__.'/includes/header.php';?><div class="d-flex justify-content-between mb-3"><div><h1 class="h3">Career categories</h1><p class="text-muted">Organize the career catalog.</p></div><button class="btn btn-primary create-action" data-bs-toggle="modal" data-bs-target="#editModal"><i class="bi bi-plus-circle"></i><span>Add category</span></button></div><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Slug</th><th>Icon</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slug'])?></td><td><?=e($r['icon'])?></td><td><button class="btn btn-sm btn-outline-primary edit" data-row='<?=e(json_encode($r))?>'>Edit</button></td></tr><?php endforeach?></tbody></table></div>
<div class="modal fade" id="editModal"><div class="modal-dialog"><form class="modal-content" action="<?=url('admin/save.php')?>" method="post" data-ajax><div class="modal-header"><h2 class="modal-title fs-5">Category</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="entity" value="category"><input type="hidden" name="id"><label class="form-label">Name</label><input class="form-control mb-3" name="name" required maxlength="80"><label class="form-label">Slug</label><input class="form-control mb-3" name="slug" required maxlength="90"><label class="form-label">Bootstrap icon name</label><input class="form-control" name="icon" maxlength="50"></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><script>document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{let r=JSON.parse(b.dataset.row),f=document.querySelector('#editModal form');Object.keys(r).forEach(k=>{if(f.elements[k])f.elements[k].value=r[k]??''});bootstrap.Modal.getOrCreateInstance(editModal).show()})</script><?php require __DIR__.'/includes/footer.php';?>
